,"silentApi","optimisticCycle","setOptimisticCycle","optimisticCurrency","setOptimisticCurrency","createFlow","loadingPayment","withLoadingPayment","loadingPaymentDetails","withLoadingPaymentDetails","handleError","currency","subscriptionData","cycle","plans","paymentMethodStatus","planName","Title","signInTo","pathname","concat","Name","state","username","signIn","_templateObject3","scrollIntoEmail","target","el","current","focus","scrollIntoView","behavior","block","handleChangeCurrency","_model$subscriptionDa","validateFlow","checkResult","planIDs","Coupon","Code","catch","undefined","_objectSpread","handleChangeCycle","_model$subscriptionDa2","onPay","payment","_await$ktFeature$get","Error","extractPaymentToken","Type","TOKEN","Details","Token","paymentToken","accountData","password","useSpecialChars","length","signupType","Email","payload","domain","cache","appName","appIntent","ignoreExplore","inviteData","referralData","persistent","trusted","get","Value","newCache","api","mode","error","paymentMethods","Card","CARD","Paypal","PAYPAL","filter","hasGuarantee","VPN","inputState","setInputState","emailConfirm","mergeInputState","key","diff","old","emailError","find","x","emailValidationError","interactive","emailConfirmError","emailConfirmValidationError","validatePayment","validateEmail","validateAsyncEmail","e","code","ALREADY_USED","EMAIL_FORMAT","NOT_ALLOWED","includes","type","expiration","card","setCard","cardErrors","method","setMethod","handleCardSubmit","parameters","paymentParameters","paypal","paypalCredit","defaultMethod","amount","AmountDue","onValidatePaypal","pay","onPaypalPay","_ref6","createModal","price","upsellPlanName","termsAndConditions","href","PROTONVPN_SETTINGS","_templateObject4","plansMap","pricing","cycles","MONTHLY","TWO_YEARS","YEARLY","features","size","name","_templateObject5","_templateObject6","width","alt","_templateObject7","src","_templateObject8","_templateObject9","paid","servers","freeName","handleCloseUpsellModal","hasDecoration","_templateObject10","map","_ref7","i","arr","style","_templateObject11","onSelect","onGetTheDeal","onChangeCycle","upsellFrom","_templateObject12","_templateObject13","ref","id","bigger","label","_templateObject14","disableChange","value","onValue","onFocus","emType","onBlur","_templateObject15","jt","_templateObject16","_templateObject17","autocomplete","getAttribute","cc","onSubmit","event","preventDefault","handle","amountAndCurrency","Currency","Amount","data","params","onMethod","newMethod","onCard","_templateObject18","flow","loading","color","fullWidth","_templateObject19","_templateObject20","_templateObject21","logo","_templateObject22","odd","margin","icon","highlight","img","_templateObject23","info","_templateObject24","countries","footer","shape","_templateObject25","_templateObject26"],"sources":["webpack://./src/app/single-signup/Step1.tsx"],"sourcesContent":["import { Fragment, ReactElement, ReactNode, useRef, useState } from 'react';
import { Link } from 'react-router-dom';

import { c } from 'ttag';

import { Button, ButtonLike } from '@proton/atoms/Button';
import { Href } from '@proton/atoms/Href';
import { Vr } from '@proton/atoms/Vr';
import { Icon, InlineLinkButton, InputFieldTwo, Price, useModalState } from '@proton/components/components';
import {
    CurrencySelector,
    FeatureCode,
    Payment as PaymentComponent,
    StyledPayPalButton,
    usePayment,
} from '@proton/components/containers';
import { KT_FF } from '@proton/components/containers/keyTransparency/ktStatus';
import NotificationButton from '@proton/components/containers/notifications/NotificationButton';
import Alert3ds from '@proton/components/containers/payments/Alert3ds';
import {
    getCountries,
    getNetShield,
    getProtectDevices,
    getStreaming,
} from '@proton/components/containers/payments/features/vpn';
import {
    AmountAndCurrency,
    CardPayment,
    PaypalPayment,
    TokenPayment,
    TokenPaymentMethod,
} from '@proton/components/containers/payments/interface';
import { createPaymentToken } from '@proton/components/containers/payments/paymentTokenHelper';
import { PlanCardFeatureList } from '@proton/components/containers/payments/subscription/PlanCardFeatures';
import {
    useActiveBreakpoint,
    useApi,
    useConfig,
    useErrorHandler,
    useFeature,
    useLoading,
    useModals,
    useNotifications,
} from '@proton/components/hooks';
import { getApiError } from '@proton/shared/lib/api/helpers/apiErrorHelper';
import { getSilentApi } from '@proton/shared/lib/api/helpers/customConfig';
import { queryCheckEmailAvailability } from '@proton/shared/lib/api/user';
import { ProductParam } from '@proton/shared/lib/apps/product';
import { getIsVPNApp } from '@proton/shared/lib/authentication/apps';
import {
    APPS,
    CLIENT_TYPES,
    CYCLE,
    PAYMENT_METHOD_TYPES,
    PLANS,
    VPN_CONNECTIONS,
    VPN_SHORT_APP_NAME,
} from '@proton/shared/lib/constants';
import { API_CUSTOM_ERROR_CODES } from '@proton/shared/lib/errors';
import { getOwnershipVerificationHeaders, mergeHeaders } from '@proton/shared/lib/fetch/headers';
import { confirmEmailValidator, emailValidator, requiredValidator } from '@proton/shared/lib/helpers/formValidators';
import { toMap } from '@proton/shared/lib/helpers/object';
import { getPricingFromPlanIDs } from '@proton/shared/lib/helpers/subscription';
import { getTermsURL, stringifySearchParams } from '@proton/shared/lib/helpers/url';
import { Currency, Cycle, Plan, PlansMap, VPNServersCountData } from '@proton/shared/lib/interfaces';
import { generatePassword } from '@proton/shared/lib/password';
import { getPlusServers, getVpnServers } from '@proton/shared/lib/vpn/features';
import clsx from '@proton/utils/clsx';
import isTruthy from '@proton/utils/isTruthy';
import noop from '@proton/utils/noop';

import { getSubscriptionPrices } from '../signup/helper';
import { SignupActionResponse, SignupCacheResult, SignupModel, SignupType } from '../signup/interfaces';
import { handleCreateUser } from '../signup/signupActions/handleCreateUser';
import { useFlowRef } from '../useFlowRef';
import Box from './Box';
import CycleSelector from './CycleSelector';
import Guarantee from './Guarantee';
import Layout from './Layout';
import StepLabel from './StepLabel';
import UpsellModal from './UpsellModal';
import swissFlag from './flag.svg';
import { getUpsellShortPlan } from './helper';
import { OnUpdate } from './interface';

const AlreadyUsedNotification = ({
    onUpdate,
    to,
    onClose,
}: {
    onUpdate: OnUpdate;
    to: Parameters<Link>[0]['to'];
    onClose?: () => void;
}) => {
    return (
        <>
            {c('Info').t`Email address already used`}
            <NotificationButton
                as={Link}
                to={to}
                onClick={() => {
                    onUpdate({ create: 'login-notification' });
                    onClose?.();
                }}
            >{c('Action').t`Sign in`}</NotificationButton>
        </>
    );
};

const FeatureItem = ({ left, text }: { left: ReactNode; text: string }) => {
    return (
        <div className="flex flex-align-items-center text-center on-mobile-flex-column flex-justify-center">
            <div className="md:mr-4 text-center">{left}</div>
            <div className="color-weak">{text}</div>
        </div>
    );
};

const BoxHeader = ({ step, title, right }: { step: number; title: string; right?: ReactNode }) => {
    return (
        <div className="flex flex-align-items-center flex-justify-space-between flex-nowrap">
            <div className="flex flex-align-items-center on-mobile-flex-column md:gap-4 gap-2">
                <div>
                    <StepLabel step={step} />
                </div>
                <h2 className="text-bold text-4xl">{title}</h2>
            </div>
            {right && <div className="flex-item-noshrink">{right}</div>}
        </div>
    );
};

const BoxContent = ({ children }: { children: ReactNode }) => {
    return <div className="pricing-box-content mt-8">{children}</div>;
};

interface InputState {
    interactive: boolean;
    focus: boolean;
}

const Step1 = ({
    plan,
    clientType,
    onComplete,
    onUpdate,
    model,
    setModel,
    upsellShortPlan,
    vpnServersCountData,
    productParam,
    hideFreePlan,
    upsellImg,
}: {
    plan: Plan | undefined;
    upsellShortPlan: ReturnType<typeof getUpsellShortPlan> | undefined;
    vpnServersCountData: VPNServersCountData;
    clientType: CLIENT_TYPES;
    onComplete: (promise: SignupActionResponse) => void;
    onUpdate: OnUpdate;
    model: SignupModel;
    setModel: (model: Partial<SignupModel>) => void;
    productParam: ProductParam;
    hideFreePlan: boolean;
    upsellImg: ReactElement;
}) => {
    const ktFeature = useFeature<KT_FF>(FeatureCode.KeyTransparencyWEB);
    const [upsellModalProps, setUpsellModal, renderUpsellModal] = useModalState();
    const { isDesktop } = useActiveBreakpoint();
    const { APP_NAME } = useConfig();
    const { createNotification } = useNotifications();
    const [email, setEmail] = useState('');
    const [confirmEmail, setConfirmEmail] = useState('');
    const trimmedEmail = email.trim();
    const [emailAsyncError, setEmailAsyncError] = useState({ email: '', message: '' });
    const emailRef = useRef<HTMLInputElement>(null);
    const emailConfirmRef = useRef<HTMLInputElement>(null);
    const freeSignupUrl = 'https://account.protonvpn.com/signup';
    const normalApi = useApi();
    const silentApi = getSilentApi(normalApi);
    const [optimisticCycle, setOptimisticCycle] = useState<CYCLE | undefined>();
    const [optimisticCurrency, setOptimisticCurrency] = useState<Currency | undefined>();

    const createFlow = useFlowRef();

    const [loadingPayment, withLoadingPayment] = useLoading();
    const [loadingPaymentDetails, withLoadingPaymentDetails] = useLoading();
    const handleError = useErrorHandler();

    const currency = optimisticCurrency || model.subscriptionData.currency;
    const cycle = optimisticCycle || model.subscriptionData.cycle;

    const { subscriptionData, plans, paymentMethodStatus } = model;
    const planName = plan?.Title;

    const signInTo = {
        pathname: `/dashboard${stringifySearchParams(
            {
                plan: plan?.Name,
                cycle: `${subscriptionData.cycle}`,
                currency: subscriptionData.currency,
            },
            '?'
        )}`,
        state: {
            username: trimmedEmail,
        },
    } as const;
    const signIn = (
        <Link
            key="signin"
            className="link link-focus text-nowrap"
            to={signInTo}
            onClick={() => onUpdate({ create: 'login' })}
        >
            {c('Link').t`Sign in`}
        </Link>
    );

    const scrollIntoEmail = (target?: 'confirm') => {
        const el = target === 'confirm' ? emailConfirmRef.current : emailRef.current;
        if (el) {
            el.focus();
            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    };

    const handleChangeCurrency = async (currency: Currency) => {
        const validateFlow = createFlow();
        setOptimisticCurrency(currency);
        onUpdate({ currency: currency });
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            currency,
            cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        ).catch(noop);
        if (!validateFlow()) {
            return;
        }
        setOptimisticCurrency(undefined);
        if (!checkResult) {
            return;
        }
        setModel({
            subscriptionData: {
                ...model.subscriptionData,
                currency,
                checkResult,
            },
        });
    };

    const handleChangeCycle = async (cycle: Cycle) => {
        const validateFlow = createFlow();
        setOptimisticCycle(cycle);
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            currency,
            cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        ).catch(noop);
        if (!validateFlow()) {
            return;
        }
        setOptimisticCycle(undefined);
        if (!checkResult) {
            return;
        }
        setModel({
            subscriptionData: {
                ...model.subscriptionData,
                cycle,
                checkResult,
            },
        });
    };

    const onPay = async (payment: PaypalPayment | TokenPayment | CardPayment | undefined) => {
        try {
            if (!payment) {
                throw new Error('Missing cache');
            }

            const extractPaymentToken = () => {
                if (payment.Type === PAYMENT_METHOD_TYPES.TOKEN) {
                    return payment.Details.Token;
                }
            };
            const paymentToken = extractPaymentToken() || '';

            const subscriptionData = {
                ...model.subscriptionData,
                payment,
            };

            setModel({
                subscriptionData,
            });

            const validateFlow = createFlow();

            const accountData = {
                username: '',
                email,
                password: generatePassword({ useSpecialChars: true, length: 16 }),
                signupType: SignupType.Email,
                payload: undefined,
                domain: '',
            };

            const cache: SignupCacheResult = {
                appName: APP_NAME,
                appIntent: undefined,
                productParam,
                // Internal app or oauth app or vpn
                ignoreExplore: true,
                accountData,
                subscriptionData,
                inviteData: model.inviteData,
                referralData: model.referralData,
                persistent: false,
                trusted: false,
                clientType,
                ktFeature: (await ktFeature.get())?.Value,
            };

            if (!validateFlow()) {
                return;
            }

            const newCache = await handleCreateUser({ cache, api: silentApi, mode: 'cro', paymentToken });
            onComplete(newCache);
        } catch (error) {
            handleError(error);
        }
    };

    const paymentMethods = [
        paymentMethodStatus?.Card && PAYMENT_METHOD_TYPES.CARD,
        paymentMethodStatus?.Paypal && PAYMENT_METHOD_TYPES.PAYPAL,
    ].filter(isTruthy);
    const hasGuarantee = plan?.Name === PLANS.VPN;

    const [inputState, setInputState] = useState<{ email: Partial<InputState>; emailConfirm: Partial<InputState> }>({
        email: {},
        emailConfirm: {},
    });

    const mergeInputState = (key: keyof typeof inputState, diff: Partial<InputState>) => {
        setInputState((old) => {
            return { ...old, [key]: { ...inputState[key], ...diff } };
        });
    };

    const emailError = [
        email === emailAsyncError.email ? emailAsyncError.message : '',
        requiredValidator(trimmedEmail),
        emailValidator(trimmedEmail),
    ].find((x) => !!x);
    const emailValidationError = inputState.email.interactive && inputState.email.focus ? emailError : undefined;
    const emailConfirmError = [confirmEmailValidator(trimmedEmail, confirmEmail.trim())].find((x) => !!x);
    const emailConfirmValidationError =
        inputState.emailConfirm.interactive && inputState.emailConfirm.focus ? emailConfirmError : undefined;

    const validatePayment = () => {
        if (loadingPayment || loadingPaymentDetails) {
            return false;
        }
        return true;
    };

    const validateEmail = () => {
        if (emailError || emailConfirmError) {
            mergeInputState('email', { interactive: true, focus: true });
            mergeInputState('emailConfirm', { interactive: true, focus: true });
            scrollIntoEmail(emailConfirmError && !emailError ? 'confirm' : undefined);
            return false;
        }
        return true;
    };

    const validateAsyncEmail = async () => {
        const validateFlow = createFlow();
        try {
            await silentApi(mergeHeaders(queryCheckEmailAvailability(email), getOwnershipVerificationHeaders('lax')));
            return true;
        } catch (e) {
            if (!validateFlow()) {
                return false;
            }
            const { code, message } = getApiError(e);
            if (
                [
                    API_CUSTOM_ERROR_CODES.ALREADY_USED,
                    API_CUSTOM_ERROR_CODES.EMAIL_FORMAT,
                    API_CUSTOM_ERROR_CODES.NOT_ALLOWED,
                ].includes(code)
            ) {
                setEmailAsyncError({ email, message });
                createNotification({
                    type: 'error',
                    text: <AlreadyUsedNotification onUpdate={onUpdate} to={signInTo} />,
                    key: 'already-used',
                    expiration: 7000,
                });
                scrollIntoEmail();
            }
            return false;
        }
    };

    const {
