import { getCreatePaymentToken, process } from './paymentTokenHelper';
import { PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';

const { STATUS_CHARGEABLE, STATUS_PENDING, STATUS_FAILED } = PAYMENT_TOKEN_STATUS;

let tab: { closed: boolean; close: jest.Mock };

beforeEach(() => {
    jest.useFakeTimers();
    tab = { closed: false, close: jest.fn() };
    jest.spyOn(window, 'open').mockReturnValue(tab as any);
});

afterEach(() => {
    jest.restoreAllMocks();
    jest.useRealTimers();
});

const options = (api: jest.Mock, signal: AbortSignal) => ({
    api,
    signal,
    Token: 'token',
    ApprovalURL: 'https://example.proton.me',
    ReturnHost: 'return.proton.me',
});

describe('process', () => {
    it('resolves and stops listening when the approval tab closes', async () => {
        const api = jest.fn();
        const controller = new AbortController();
        const promise = process(options(api, controller.signal), 10);
        tab.closed = true;
        jest.advanceTimersByTime(10);
        await expect(promise).resolves.toBeUndefined();
        jest.advanceTimersByTime(100);
        expect(api).not.toHaveBeenCalled();
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves on abort and clears scheduled checks', async () => {
        const api = jest.fn();
        const controller = new AbortController();
        const promise = process(options(api, controller.signal), 10);
        controller.abort();
        await expect(promise).resolves.toBeUndefined();
        expect(tab.close).toHaveBeenCalled();
        expect(jest.getTimerCount()).toBe(0);
    });

    it('polls at the configured interval and settles on terminal status', async () => {
        const api = jest.fn().mockResolvedValueOnce({ Status: STATUS_PENDING }).mockResolvedValueOnce({ Status: STATUS_CHARGEABLE });
        const controller = new AbortController();
        const promise = process(options(api, controller.signal), 10, 20);
        window.dispatchEvent(new MessageEvent('message', { origin: 'https://return.proton.me', data: {} }));
        await Promise.resolve();
        expect(api).toHaveBeenCalledTimes(1);
        jest.advanceTimersByTime(19);
        expect(api).toHaveBeenCalledTimes(1);
        jest.advanceTimersByTime(1);
        await expect(promise).resolves.toBeUndefined();
        expect(api).toHaveBeenCalledTimes(2);
        expect(jest.getTimerCount()).toBe(0);
    });
});

describe('getCreatePaymentToken', () => {
    it('returns chargeable tokens without invoking verification', async () => {
        const verify = jest.fn();
        const api = jest.fn().mockResolvedValue({ Token: 'token', Status: STATUS_CHARGEABLE });
        const create = getCreatePaymentToken(verify);
        await expect(create({ api, params: { Payment: { Type: 0 as any, Details: {} as any } } })).resolves.toBeDefined();
        expect(verify).not.toHaveBeenCalled();
    });

    it('passes pending tokens to the injected verifier', async () => {
        const paymentMethod = { Payment: { Type: 0, Details: {} } } as any;
        const verify = jest.fn().mockResolvedValue(paymentMethod);
        const api = jest.fn().mockResolvedValue({ Token: 'token', Status: STATUS_PENDING, ApprovalURL: 'https://example.proton.me', ReturnHost: 'return.proton.me' });
        const create = getCreatePaymentToken(verify);
        await expect(create({ api, params: paymentMethod })).resolves.toBe(paymentMethod);
        expect(verify).toHaveBeenCalledWith({ mode: undefined, Payment: paymentMethod.Payment, Token: 'token', ApprovalURL: 'https://example.proton.me', ReturnHost: 'return.proton.me' });
    });

    it('rejects failed tokens without invoking verification', async () => {
        const verify = jest.fn();
        const api = jest.fn().mockResolvedValue({ Token: 'token', Status: STATUS_FAILED });
        const create = getCreatePaymentToken(verify);
        await expect(create({ api, params: { Payment: { Type: 0 as any, Details: {} as any } } })).rejects.toThrow();
        expect(verify).not.toHaveBeenCalled();
    });
});
